BEGIN TRANSACTION;
CREATE TABLE machines (
	id INTEGER NOT NULL, 
	machine_code VARCHAR(30) NOT NULL, 
	machine_name VARCHAR(100) NOT NULL, 
	department VARCHAR(100), 
	manufacturer VARCHAR(100), 
	installation_date DATE, 
	status VARCHAR(20), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE maintenance (
	id INTEGER NOT NULL, 
	machine_id INTEGER NOT NULL, 
	prediction_id INTEGER, 
	priority VARCHAR(20), 
	status VARCHAR(20), 
	remarks TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(machine_id) REFERENCES machines (id), 
	FOREIGN KEY(prediction_id) REFERENCES predictions (id)
);
CREATE TABLE predictions (
	id INTEGER NOT NULL, 
	machine_id INTEGER NOT NULL, 
	air_temperature FLOAT NOT NULL, 
	process_temperature FLOAT NOT NULL, 
	rotational_speed FLOAT NOT NULL, 
	torque FLOAT NOT NULL, 
	tool_wear FLOAT NOT NULL, 
	load_density FLOAT, 
	rpm_torque_interaction FLOAT, 
	temperature_difference FLOAT, 
	temperature_ratio FLOAT, 
	load_stress FLOAT, 
	tool_wear_mean_10 FLOAT, 
	air_temp_mean_10 FLOAT, 
	prediction VARCHAR(50) NOT NULL, 
	probability FLOAT NOT NULL, 
	healthy_probability FLOAT, 
	warning_probability FLOAT, 
	critical_probability FLOAT, 
	confidence NUMERIC(5, 2), 
	process_temp_mean_10 FLOAT, 
	rpm_std_10 FLOAT, 
	predicted_class INTEGER, 
	model_version VARCHAR(100), 
	predicted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(machine_id) REFERENCES machines (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	company_name VARCHAR(150) NOT NULL, 
	admin_name VARCHAR(100) NOT NULL, 
	email VARCHAR(100) NOT NULL, 
	username VARCHAR(50) NOT NULL, 
	password VARCHAR(255) NOT NULL, 
	role VARCHAR(50), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE INDEX ix_users_username ON users (username);
CREATE INDEX ix_users_id ON users (id);
CREATE INDEX ix_users_company_name ON users (company_name);
CREATE INDEX ix_machines_status ON machines (status);
CREATE UNIQUE INDEX ix_machines_machine_code ON machines (machine_code);
CREATE INDEX ix_machines_id ON machines (id);
CREATE INDEX ix_predictions_predicted_at ON predictions (predicted_at);
CREATE INDEX ix_predictions_id ON predictions (id);
CREATE INDEX ix_predictions_machine_id ON predictions (machine_id);
CREATE INDEX ix_maintenance_created_at ON maintenance (created_at);
CREATE INDEX ix_maintenance_status ON maintenance (status);
CREATE INDEX ix_maintenance_machine_id ON maintenance (machine_id);
CREATE INDEX ix_maintenance_id ON maintenance (id);
CREATE INDEX ix_maintenance_prediction_id ON maintenance (prediction_id);
COMMIT;
